// web.ts — minimal web access: SearXNG search + page fetch as markdown.
//
// Config (in priority order):
//   1. SEARXNG_BASE_URL env var
//   2. "searxngBaseUrl" in ~/.pi/web-search.json
//   3. http://localhost:8888
//
// SearXNG must enable the JSON format in settings.yml:
//   search:
//     formats: [html, json]
//
// web_fetch additionally clones github.com/owner/repo URLs locally (shallow,
// depth 1) instead of scraping the rendered page, so the agent gets real file
// contents. Root URLs -> tree + README, /tree/ -> directory listing, /blob/ ->
// file contents. Requires `git` on PATH. Falls back to a normal HTTP fetch on
// any failure (no git, private repo, bad ref, network error). Clones are
// cached under ~/.pi/web-fetch-cache/github/ and reused across calls.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { existsSync, readFileSync } from "node:fs";
import { mkdir, readdir, readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import TurndownService from "turndown";
import { tables, strikethrough } from "turndown-plugin-gfm";

const execFileAsync = promisify(execFile);

const UA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120 Safari/537.36";

function searxngBaseUrl(): string {
	const env = process.env.SEARXNG_BASE_URL?.trim();
	if (env) return env.replace(/\/+$/, "");
	const configPath = join(homedir(), ".pi", "web-search.json");
	if (existsSync(configPath)) {
		const cfg = JSON.parse(readFileSync(configPath, "utf-8"));
		if (typeof cfg.searxngBaseUrl === "string" && cfg.searxngBaseUrl.trim()) {
			return cfg.searxngBaseUrl.trim().replace(/\/+$/, "");
		}
	}

	return "http://localhost:8888";
}

function combinedSignal(signal: AbortSignal | undefined, ms: number): AbortSignal {
	const timeout = AbortSignal.timeout(ms);
	return signal ? AbortSignal.any([signal, timeout]) : timeout;
}

// ---------- HTML -> markdown ----------

function htmlToMarkdown(html: string, base: string): string {
	const converter = new TurndownService({
		headingStyle: "atx",
		codeBlockStyle: "fenced",
		bulletListMarker: "-",
		preformattedCode: true,
	});
	converter.use([tables, strikethrough]);
	converter.remove(["script", "style", "noscript", "svg", "template", "head", "iframe", "nav"]);

	function resolve(target: string | null): string | null {
		if (!target?.trim()) return null;
		try {
			const url = new URL(target, base);
			if (/^(javascript|data|vbscript|mailto|tel):$/i.test(url.protocol)) return null;
			return url.href.replace(/\(/g, "%28").replace(/\)/g, "%29");
		} catch {
			return null;
		}
	}

	converter.addRule("resolvedLink", {
		filter: "a",
		replacement(content, node) {
			const url = resolve(node.getAttribute("href"));
			return url && content ? `[${content}](${url})` : content;
		},
	});
	converter.addRule("resolvedImage", {
		filter: "img",
		replacement(_content, node) {
			const alt = converter.escape(node.getAttribute("alt") || "");
			const url = resolve(node.getAttribute("src"));
			return url ? `![${alt}](${url})` : alt;
		},
	});
	converter.addRule("strikethrough", {
		filter: ["del", "s", "strike"],
		replacement: (content) => `~~${content}~~`,
	});
	converter.addRule("preformattedBlock", {
		filter: "pre",
		replacement(_content, node) {
			const code = node.textContent;
			const runs = code.match(/`{3,}/g) || [];
			const fence = "`".repeat(Math.max(3, ...runs.map((run) => run.length + 1)));
			const language = (node.firstChild?.getAttribute?.("class") || "").match(/language-([\w+-]+)/)?.[1] || "";
			return `\n\n${fence}${language}\n${code}${code.endsWith("\n") ? "" : "\n"}${fence}\n\n`;
		},
	});
	// GFM requires a header and equal-width rows, even for irregular HTML tables.
	converter.addRule("normalizedTable", {
		filter: "table",
		replacement(_content, node) {
			const rows = Array.from(node.rows, (row) => Array.from(row.cells, (cell) =>
				converter.turndown(cell.innerHTML).replace(/\|/g, "\\|").replace(/\s*\n\s*/g, "<br>")));
			const width = Math.max(0, ...rows.map((row) => row.length));
			if (!width) return "";
			const line = (row) => `| ${Array.from({ length: width }, (_, i) => row[i] || "").join(" | ")} |`;
			const hasHeader = Array.from(node.rows[0].cells).every((cell) => cell.nodeName === "TH") ||
				node.rows[0].parentNode.nodeName === "THEAD";
			const header = hasHeader ? rows.shift() : [];
			return `\n\n${[line(header), line(Array(width).fill("---")), ...rows.map(line)].join("\n")}\n\n`;
		},
	});
	// Turndown wraps input in a body element, where HTML parsers can discard
	// the HEAD tags but leave their contents. Remove that section before parsing.
	return converter.turndown(html.replace(/<head\b[^>]*>[\s\S]*?<\/head\s*>/gi, "").replace(/^\uFEFF/, ""));
}

// ---------- GitHub repo cloning (root/tree/blob URLs) ----------

interface GithubTarget {
	owner: string;
	repo: string;
	kind: "root" | "tree" | "blob";
	ref?: string;
	path?: string;
}

// Only handles code URLs (root, /tree/<ref>/..., /blob/<ref>/...). Issues, PRs,
// wiki, actions, etc. return null and fall through to the normal HTML fetch.
// Branch names containing "/" and commit-SHA refs are not disambiguated here
// (git clone --branch will simply fail for those and we fall back to a plain fetch).
function parseGithubUrl(url: string): GithubTarget | null {
	let u: URL;
	try {
		u = new URL(url);
	} catch {
		return null;
	}
	if (!/^(www\.)?github\.com$/i.test(u.hostname)) return null;
	const parts = u.pathname.split("/").filter(Boolean);
	if (parts.length < 2) return null;
	const owner = parts[0];
	const repo = parts[1].replace(/\.git$/i, "");
	if (parts.length === 2) return { owner, repo, kind: "root" };
	const kind = parts[2];
	if ((kind === "tree" || kind === "blob") && parts[3]) {
		return { owner, repo, kind, ref: parts[3], path: parts.slice(4).join("/") || undefined };
	}
	return null;
}

function githubCacheDir(owner: string, repo: string, ref: string | undefined): string {
	const root = join(homedir(), ".pi", "web-fetch-cache", "github");
	const safeRef = (ref ?? "HEAD").replace(/[^\w.-]+/g, "_");
	return join(root, `${owner}__${repo}__${safeRef}`);
}

async function ensureGithubClone(
	owner: string,
	repo: string,
	ref: string | undefined,
	signal: AbortSignal | undefined,
): Promise<string> {
	const dir = githubCacheDir(owner, repo, ref);
	if (existsSync(join(dir, ".git"))) return dir; // reuse cached shallow clone
	await mkdir(join(homedir(), ".pi", "web-fetch-cache", "github"), { recursive: true });
	const args = ["clone", "--depth", "1", "--single-branch"];
	if (ref) args.push("--branch", ref);
	args.push(`https://github.com/${owner}/${repo}.git`, dir);
	await execFileAsync("git", args, { signal: combinedSignal(signal, 60_000) });
	return dir;
}

function isReadmeName(name: string): boolean {
	return /^readme(\.(md|markdown|txt|rst))?$/i.test(name);
}

async function readGithubRoot(dir: string): Promise<string> {
	const entries = await readdir(dir, { withFileTypes: true });
	const visible = entries.filter((e) => e.name !== ".git");
	const tree = visible
		.map((e) => (e.isDirectory() ? `${e.name}/` : e.name))
		.sort()
		.join("\n");
	const readmeName = visible.find((e) => e.isFile() && isReadmeName(e.name))?.name;
	const readme = readmeName ? await readFile(join(dir, readmeName), "utf8") : null;
	return `# Repo tree (top level)\n\n${tree}\n\n${readme ? `# ${readmeName}\n\n${readme}` : "(no README found)"}`;
}

async function readGithubDir(dir: string, subpath: string): Promise<string> {
	const target = join(dir, subpath);
	const entries = await readdir(target, { withFileTypes: true });
	const listing = entries
		.filter((e) => e.name !== ".git")
		.map((e) => (e.isDirectory() ? `${e.name}/` : e.name))
		.sort()
		.join("\n");
	return `# Directory: ${subpath || "/"}\n\n${listing}`;
}

async function readGithubFile(dir: string, subpath: string): Promise<string> {
	const buf = await readFile(join(dir, subpath));
	if (buf.includes(0)) return `(binary file, ${buf.length} bytes, not shown)`;
	return buf.toString("utf8");
}

async function fetchGithub(
	gh: GithubTarget,
	originalUrl: string,
	maxChars: number,
	signal: AbortSignal | undefined,
) {
	const dir = await ensureGithubClone(gh.owner, gh.repo, gh.ref, signal);
	const text =
		gh.kind === "root"
			? await readGithubRoot(dir)
			: gh.kind === "tree"
				? await readGithubDir(dir, gh.path ?? "")
				: await readGithubFile(dir, gh.path ?? "");
	const truncated = text.length > maxChars;
	return {
		content: [{ type: "text" as const, text: truncated ? text.slice(0, maxChars) + "\n\n[truncated]" : text }],
		details: {
			url: originalUrl,
			source: "github-clone",
			clonePath: dir,
			kind: gh.kind,
			chars: text.length,
			truncated,
		},
	};
}

// ---------- tools ----------

export default function (pi: ExtensionAPI) {
	pi.registerTool({
		name: "web_search",
		label: "Web Search",
		description:
			"Search the web using the configured SearXNG instance. Returns titles, URLs, and snippets. Follow up with web_fetch on a result URL to read a page.",
		promptSnippet: "Search the web via the local SearXNG instance",
		promptGuidelines: [
			"Use web_search for web lookups; follow up with web_fetch on promising result URLs to read full pages.",
		],
		parameters: Type.Object({
			query: Type.String({ description: "Search query" }),
			count: Type.Optional(Type.Number({ description: "Max results (default 10, max 25)" })),
		}),
		async execute(_id, params, signal) {
			const count = Math.min(Math.max(params.count ?? 10, 1), 25);
			const base = searxngBaseUrl();
			const res = await fetch(`${base}/search?q=${encodeURIComponent(params.query)}&format=json`, {
				headers: { Accept: "application/json", "User-Agent": UA },
				signal: combinedSignal(signal, 20_000),
			});
			const text = await res.text();
			if (!res.ok || text.trimStart().startsWith("<")) {
				throw new Error(
					`SearXNG at ${base} returned HTTP ${res.status} (non-JSON). ` +
						`Enable the JSON format in settings.yml: search.formats: [html, json]`,
				);
			}
			const data = JSON.parse(text) as {
				results?: { title?: string; url?: string; content?: string }[];
				answers?: string[];
			};
			const results = (data.results ?? []).slice(0, count);
			if (results.length === 0) {
				return { content: [{ type: "text", text: "No results found." }], details: { base, count: 0 } };
			}
			const lines: string[] = [];
			for (const a of (data.answers ?? []).slice(0, 2)) lines.push(`Answer: ${a}`, "");
			results.forEach((r, i) => {
				lines.push(`${i + 1}. ${r.title ?? "(no title)"}`, `   ${r.url ?? ""}`);
				if (r.content) lines.push(`   ${r.content}`);
				lines.push("");
			});
			return {
				content: [{ type: "text", text: lines.join("\n").trim() }],
				details: { base, count: results.length },
			};
		},
	});

	pi.registerTool({
		name: "web_fetch",
		label: "Web Fetch",
		description:
			"Fetch a URL and return its content as markdown. HTML pages are converted to markdown-ish text; other content types are returned as-is. github.com repo/tree/blob URLs are cloned locally (shallow) instead of scraped, returning real file contents.",
		promptSnippet: "Fetch a URL as markdown (clones github.com repo URLs)",
		promptGuidelines: [
			"Use web_fetch to read a specific page as markdown when you already know its URL.",
			"Use web_fetch directly on github.com/owner/repo (or /tree/<ref>/... or /blob/<ref>/...) URLs instead of scraping them; it clones the repo shallowly and returns the real tree/README, directory listing, or file contents.",
		],
		parameters: Type.Object({
			url: Type.String({ description: "URL to fetch" }),
			maxChars: Type.Optional(Type.Number({ description: "Max characters to return (default 20000)" })),
		}),
		async execute(_id, params, signal) {
			const maxChars = Math.min(Math.max(params.maxChars ?? 20_000, 1000), 200_000);

			const gh = parseGithubUrl(params.url);
			if (gh) {
				try {
					return await fetchGithub(gh, params.url, maxChars, signal);
				} catch {
					// Clone failed (no git, private repo, bad ref, network) -- fall through to a normal HTTP fetch.
				}
			}

			const res = await fetch(params.url, {
				headers: { "User-Agent": UA, Accept: "text/html,application/xhtml+xml,text/plain,text/markdown,*/*" },
				redirect: "follow",
				signal: combinedSignal(signal, 25_000),
			});
			if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${params.url}`);
			const contentType = res.headers.get("content-type") ?? "";
			const body = await res.text();
			const isHtml = /\b(?:text\/html|application\/xhtml\+xml)\b/i.test(contentType) ||
				/^\s*(?:<!doctype\s+html\b|<html[\s>])/i.test(body);
			const markdown = isHtml ? htmlToMarkdown(body, res.url || params.url) : body;
			const truncated = markdown.length > maxChars;
			return {
				content: [{ type: "text", text: truncated ? markdown.slice(0, maxChars) + "\n\n[truncated]" : markdown }],
				details: { url: res.url || params.url, status: res.status, contentType, chars: markdown.length, truncated },
			};
		},
	});
}
